  function findComp(n,nm){
    if(n.type==='COMPONENT' && n.name===nm) return n;
    if('children' in n){ for(const c of n.children){ const r=findComp(c,nm); if(r) return r; } }
    return null;
  }
  async function compInstance(name, w, h, color){
    const comp = findComp(mediaHolder,name);
    if(!comp) return null;
    let inst;
    try{ inst = (await figma.importComponentByKeyAsync(comp.key)).createInstance(); }
    catch(e){ inst = comp.clone(); }
    inst.resize(w,h);
    if(color && inst.type==='INSTANCE' && 'fills' in inst){ try{inst.fills=[{type:'SOLID',color}];}catch(e){} }
    return inst;
  }
  function setFillsVector(node, color){
    if('fills' in node){
      node.fills = node.fills.map(f=>{
        try{ return {type:'SOLID',color}; }catch(e){return f;} });
    }
    if('children' in node){ for(const c of node.children){ setFillsVector(c,color);} }
  }

  const parent = figma.getNodeById("15:2");
