    t.resize(w,h); return t;
  }
  function sect(x,y,w,h,color){ const f=figma.createFrame(); f.x=x;f.y=y;f.resize(w,h); f.fills=color?[{type:'SOLID',color}]:[]; return f; }

  // ============ ANNOUNCEMENT BAR ============
  const an=sect(0,0,1440,44,BLACK);
  an.appendChild(text(330,10,500,24,"Sign up and get 20% off to your first order.",14,"Plus Jakarta Sans","Regular",WHITE,'CENTER'));
  const sign=text(700,10,160,24,"Sign Up Now",14,"Plus Jakarta Sans","Medium",WHITE);
  sign.textDecoration="UNDERLINE"; an.appendChild(sign);
  const close=await compInstance("Icon_Close",24,24); if(close){close.x=1390;close.y=10;setFillsVector(close,WHITE);an.appendChild(close);}
  parent.appendChild(an);

  // ============ HEADER ============
  const hd=sect(0,44,1440,90,WHITE);
  hd.strokes=[{type:'SOLID',color:OUT}]; hd.strokeBottomWeight=1; hd.strokeTopWeight=0; hd.strokeLeftWeight=0; hd.strokeRightWeight=0;
  hd.appendChild(text(100,27,180,40,"SHOP.CO",30,"Archivo Black","Regular",BLACK));
  const nav=["Shop","On Sale","New Arrivals","Brands"]; let nx=330;
  for(const it of nav){
    const t=text(nx,33,120,26,it,16,"Plus Jakarta Sans","SemiBold",BLACK); hd.appendChild(t);
    if(it==="Shop"){ const cd=await compInstance("Icon_Chevron_Down",16,16); if(cd){cd.x=nx+t.width+6;cd.y=37;setFillsVector(cd,BLACK);hd.appendChild(cd);} nx+=t.width+36;}
    else if(it==="On Sale"){ nx+=t.width+44;}
    else if(it==="New Arrivals"){ nx+=t.width+44;}
    else if(it==="Brands"){ nx+=t.width;}
  }
  const search=sect(600,21,470,48,HERO); search.cornerRadius=24; hd.appendChild(search);
  const si=await compInstance("Icon_Search",20,20); if(si){si.x=616;si.y=35;setFillsVector(si,GRAY);hd.appendChild(si);}
  hd.appendChild(text(648,34,300,22,"Search for products...",14,"Plus Jakarta Sans","Regular",GRAY2));
  const cart=await compInstance("Icon_Cart",24,24); if(cart){cart.x=1185;cart.y=33;cart.name="Cart";setFillsVector(cart,BLACK);hd.appendChild(cart);}
  const acct=await compInstance("Icon_Account",24,24); if(acct){acct.x=1235;acct.y=33;setFillsVector(acct,BLACK);hd.appendChild(acct);}
  parent.appendChild(hd);
  console.log("chrome done");
}
